// features/lifecycle.feature: Search and the status filter apply together
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("search and the status filter apply together", { tag: "@LIF-14" }, async ({ apiAs, factory }) => {
  // Arrange
  const word = uniqueName("Lif14");
  const draft = await factory.vendor({ name: `${word} Draft` });
  const { vendor: inReview } = await factory.vendorInReview({ name: `${word} Review` });
  expect(draft.status, "the draft vendor stays in draft").toBe("draft");
  const member = await apiAs("member");

  // Act
  const response = await member.get("/api/vendors", { params: { q: word, status: "in_review" } });

  // Assert
  const page = await expectStatus<{ items: { id: string; status: string }[]; total: number }>(response, 200);
  expect(page.items.map((v) => v.id)).toEqual([inReview.id]);
  expect(page.items[0].status).toBe("in_review");
  expect(page.total).toBe(1);
});
